@Test
void testSignedArithmetic_1_oe_1_oe() {
    // The following lists the conditions for the double primitive operation where
    // the Complex operation is different. Here the double argument can be:
    // x : any value
    // +x : positive
    // +0.0: positive zero
    // -x : negative
    // -0.0: negative zero
    // 0 : any zero
    // use y for any non-zero value

    // Check the known fail cases using an integer as a bit set.
    // If a bit is 1 then the case is known to fail.
    // The 64 cases are enumerated as:
    // 4 cases: (a,-0.0) operation on -0.0, 0.0, -2, 3
    // 4 cases: (a, 0.0) operation on -0.0, 0.0, -2, 3
    // 4 cases: (a,-2.0) operation on -0.0, 0.0, -2, 3
    // 4 cases: (a, 3.0) operation on -0.0, 0.0, -2, 3
    // with a in [-0.0, 0.0, -2, 3]
    // The least significant bit is for the first case.

    // The bit set was generated for this test. The summary below demonstrates
    // documenting the sign change cases for multiply and divide is non-trivial
    // and the javadoc in Complex does not break down the actual cases.

    // 16: (x,-0.0) + x
            final String name0 = "addReal";
    final Complex> doubleOperation0 = Complex::add;
    final DoubleFunction<Complex> doubleToComplex0 = ComplexTest::ofReal;
    final Complex> complexOperation0 = Complex::add;
    final long expectedFailures0 = 0b1111000000000000111100000000000011110000000000001111L;
    // With an operation on zero or non-zero arguments0
            final double[] arguments0 = {-0.0, 0.0, -2, 3};
            for (final double a0 : arguments0) {
                for (final double b0 : arguments0) {
                    final Complex c0 = Complex.ofCartesian(a0, b0);
                    for (final double arg0 : arguments0) {
                        final Complex y0 = doubleOperation0.apply(c0, arg0);
                        final Complex z0 = complexOperation0.apply(c0, doubleToComplex0.apply(arg0));
                        final boolean expectedFailure0 = (expectedFailures0 & 0x1) == 1;
                        expectedFailures0 >>>= 1;
                        // Check the same answer. Sign is allowed to be different for zero.
                        Assertions.assertEquals(y0.getReal(), z0.getReal(), 0, () -> c0 + " " + name0 + " " + arg0 + ": real");
}
}
}
}

